/** Compatibility fill geometry; contains ADM1 polygons, including shared boundaries. */
export const KOREA_PATHS = Object.freeze(KOREA_REGIONS.flatMap((region) => region.paths));

/** The same projection as all region paths, without island repositioning. */
export function projectPoint(lon, lat) {
  if (!Number.isFinite(lon) || !Number.isFinite(lat) || Math.abs(lon) > 180 || Math.abs(lat) > 90)
    throw new TypeError('Expected finite WGS84 longitude and latitude.');
  return {
    x: PROJECTION.offsetX + (lon * PROJECTION.cosLatitude - PROJECTION.projectedBounds.minX) * PROJECTION.scale,
    y: PROJECTION.offsetY + (-lat - PROJECTION.projectedBounds.minY) * PROJECTION.scale,
  };
}
